def f(inputs):
    results = []

    for L, polygon1, polygon2 in inputs:
        if L == 0:
            break

        # calculate the area of the first polygon
        n = len(polygon1)
        area1 = 0
        for i in range(n):
            j = (i + 1) % n
            area1 += polygon1[i][0] * polygon1[j][1]
            area1 -= polygon1[j][0] * polygon1[i][1]
        area1 = abs(area1) / 2

        # calculate the area of the second polygon
        n = len(polygon2)
        area2 = 0
        for i in range(n):
            j = (i + 1) % n
            area2 += polygon2[i][0] * polygon2[j][1]
            area2 -= polygon2[j][0] * polygon2[i][1]
        area2 = abs(area2) / 2

        # calculate the intersection area
        intersection_area = 0
        for p in polygon1:
            if point_inside_polygon(p, polygon2):
                intersection_area += 1
        for p in polygon2:
            if point_inside_polygon(p, polygon1):
                intersection_area += 1

        # calculate the result
        result = area1 + area2 - intersection_area
        results.append(str(result))

    return '\n'.join(results)


def point_inside_polygon(point, polygon):
    n = len(polygon)
    inside = False
    p1x, p1y = polygon[0]
    for i in range(n + 1):
        p2x, p2y = polygon[i % n]
        if point[1] > min(p1y, p2y):
            if point[1] <= max(p1y, p2y):
                if point[0] <= max(p1x, p2x):
                    if p1y!= p2y:
                        xinters = (point[1] - p1y) * (p2x - p1x) / (p2y - p1y) + p1x
                    if p1x == p2x or point[0] <= xinters:
                        inside = not inside
        p1x, p1y = p2x, p2y
    return inside


